Added request logging via Next.js proxy in `proxy.ts:1`.

```ts
import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

export function proxy(request: NextRequest) {
  const { method, nextUrl } = request;
  const url = `${nextUrl.pathname}${nextUrl.search}`;
  console.log(`[request] ${method} ${url}`);

  return NextResponse.next();
}
```

This logs every incoming route request to the server console. I also verified it compiles with `npm run build`.

